    [11] = {code = "Bastok 3-2", s = {["|1"] = "Obtain a Hare Meat.", ["|2"] = "Speak to Davyad (K-6) in Bastok Mines inside the corner house on the upper deck.", ["|3"] = "Head to Gusgen Mines (or Survival Guide, Zulkheim Region) from Konschtat Highlands and proceed to (J-7).", ["|4"] = "Once inside the Mines, follow these directions to arrive at the pond at (J-7):", ["|5"] = "Trade the Hare Meat to the ??? to spawn Blind Moby, a Pugil NM.", ["|6"] = "Trade the Glocolite to any Gate Guard to finish the Mission."}},
    [12] = {code = "Bastok 3-3", s = {["|1"] = "Speak to Lucius, located at the Aide's Office (J/I-9) in the Metalworks HP #1 until you receive Letter to the ambassador.", ["|10"] = "Sneak/Invisible (Status) or Prism Powder/ Silent Oil.", ["|11"] = "Some form of Reraise and Warp is also helpful.", ["|12"] = "A map of Qufim Island and a Map of Delkfutt's Tower may be purchased from Promurouve at (H-7) in Lower Jeuno (inside the building) or", ["|13"] = "Make your way to Port Jeuno and zone into Qufim Island.", ["|14"] = "Enter Lower Delkfutt's Tower at (F-6).", ["|15"] = "Once inside prepare for a long walk.", ["|16"] = "Floor 1: (Lower Delkfutt's Tower)", ["|17"] = "Floor 2:", ["|18"] = "Floor 3:", ["|19"] = "Floor 4: (Middle Delkfutt's Tower Map 1)", ["|2"] = "Head to the Bastokan Embassy in Ru'Lude Gardens (H-10) and speak with Goggehn.", ["|20"] = "Floor 5: (half way there)", ["|21"] = "Floor 6:", ["|22"] = "Floor 7:", ["|23"] = "Floor 8:", ["|24"] = "Floor 9:", ["|25"] = "Floor 8: (again)", ["|26"] = "Floor 9: (again)", ["|27"] = "Floor 10: (Upper Delkfutt's Tower Map 1)", ["|28"] = "Kill Porphyrion and any aggro you may have.", ["|29"] = "Once you have your Key, trade it to the elevator on the floor at (H-8) inside Porphyrion's room.", ["|3"] = "Head to Lower Delkfutt's Tower (E-8) Map 1 and enter the Basement by clicking the Cermet Door.", ["|30"] = "Walk down the long staircase after using the elevator to get to the Basement.", ["|31"] = "Once you reach the Basement, head east into a large room and trade your Delkfutt Key (or interact if you have the Delkfutt key) to the", ["|32"] = "Return to the Bastokan Embassy in Ru'Lude Gardens and click the Door: Bastokan Emb. for a cutscene to complete the Mission.", ["|33"] = "You do not have to be on this Mission to receive a Delkfutt Key from Porphyrion.", ["|4"] = "Return to the Bastokan Embassy in Ru'Lude Gardens and click the Door: Bastokan Emb. for a cutscene to complete the Mission.", ["|5"] = "Next, you can open the door at (J-8).", ["|6"] = "Click it to travel to Upper Delkfutt's Tower.", ["|7"] = "Porphyrion, kill this NM then trade the Delkfutt Key it drops to the Elevator directly beside it.", ["|8"] = "After using the elevator, proceed down the spiral stair case for two zones, through the Cermet Door then walk through the large room", ["|9"] = "Return to the Bastokan Embassy in Ru'Lude Gardens and click the Door: Bastokan Emb. for a cutscene to complete the Mission."}},
    [13] = {code = "Bastok 4-1", s = {["|1"] = "This Mission is identical for all three Nations.", ["|10"] = "Examine the door at the end of the hallway in Neptune's Spire to enter the Tenshodo H.Q.", ["|11"] = "Once inside speak with Aldo at (J-8) for the Silver bell.", ["|12"] = "Yagudo torch:", ["|13"] = "Coruscant rosary and Black matinee necklace:", ["|14"] = "Crest of Davoi:", ["|15"] = "Elesca - Northern San d'Oria (I-8)", ["|16"] = "Violitte - Southern San d'Oria (G-10)", ["|17"] = "Karine - Bastok Markets (H-9)", ["|18"] = "Rex - Port Bastok (J-7)", ["|19"] = "Mhoji Roccoruh - Port Windurst (G-9)", ["|2"] = "To flag the Mission, speak with Goggehn then click the innermost Door: Bastokan Emb. in Ru'Lude Gardens (H-10) for the Archducal audience", ["|20"] = "Pehki Machumaht - Windurst Woods (H-11)", ["|21"] = "Promurouve - Lower Jeuno (H-7)", ["|22"] = "Rusese - Upper Jeuno (H-6)", ["|23"] = "Mages will need Echo Drops for this area.", ["|24"] = "Everything in this area aggros sound, therefore only Sneak is necessary.", ["|25"] = "Set your Home Point in Jeuno and bring some form of Warp.", ["|26"] = "You will have to kill two level 40-45 NM in this zone.", ["|27"] = "Enter Beadeaux from Pashhow Marshlands at (L-11).", ["|28"] = "Follow the left wall to a tunnel at (H-7).", ["|29"] = "Inside follow the right wall until you get to a Mute device inside a circular room.", ["|3"] = "Click on the door to the Audience Chamber in Ru'Lude Gardens (H-5) for a cutscene and the Letter to Aldo.", ["|30"] = "Head south after you have been silenced and then follow the tunnel west until you reach the exit at (F-8).", ["|31"] = "Outside reapply silence at the Mute in front of you (There is another Afflictor in this area) and then head southwest to a ramp at (E-10).", ["|32"] = "Once you are on the upper area turn right and go across the bridge.", ["|33"] = "Here you will find De'Vyu Headhunter.", ["|34"] = "Now turn around and head northeast back toward where you came from.", ["|35"] = "Follow the right wall now until you reach (F-6).", ["|36"] = "Here you will find Go'Bhu Gascon, another Warrior NM.", ["|37"] = "Head back to Jeuno.", ["|38"] = "Trade both items to Sattal-Mansal.", ["|39"] = "Make your way to Davoi.", ["|4"] = "Speak to Aldo in Lower Jeuno, in the back of the Neptune's Spire Tenshodo H.Q. for a cutscene and the Silver bell.", ["|40"] = "Once you're in Davoi, go to (G-7).", ["|41"] = "Drop invisible and click on the Wall of Dark Arts, you'll be able to enter the Monastic Cavern.", ["|42"] = "Inside there will not be any enemies.", ["|43"] = "Go back to Upper Jeuno, trigger the cutscene with Paya-Sabya, go to Lower Jeuno, and trigger the cutscene with Muckvix to receive Yagudo", ["|44"] = "Go back to Altar Room for an initial cutscene with Fickie, and then a subsequent cutscene when touching the magicite.", ["|45"] = "Seems that the Yagudo torch portion is required, even if someone else can get you through.", ["|46"] = "You will need both Silent Oils and Prism Powders.", ["|47"] = "There are areas of this zone where anyone under Level 60 will still receive aggro.", ["|48"] = "Enter the Castle and head to the Brass Door at (I-8).", ["|49"] = "Proceed upstairs, you'll be on Map 2.", ["|5"] = "Speak to Paya-Sabya in Upper Jeuno (I-8) and then Muckvix at (H-9) inside Muckvix's Junk Shop in Lower Jeuno for the Yagudo torch.", ["|50"] = "On this map, head north (without falling off) to a hallway entrance at (I-7) which will lead you to Map 7.", ["|51"] = "Here follow the right wall until you reach a door at (H-9).", ["|52"] = "At the door, light the Torch and you will be taken through.", ["|53"] = "Head south and take a right to another Brass Door.", ["|54"] = "Inside you will be in the Altar Room, an area with no mobs.", ["|55"] = "If the cutscene did not trigger, and you received a message that the \"magicite glows ominously,\" then try the recommendation listed above", ["|56"] = "Everything in this area aggros, therefore Sneak and Invisible are required.", ["|57"] = "From the entrance of Beadeaux, hug the left wall until you reach a tunnel entrance at (H-7).", ["|58"] = "Make your way down the tunnel and once you reach the intersection, go left.", ["|59"] = "There are no monsters in here.", ["|6"] = "Obtain the 3 Magicite Key Items.", ["|60"] = "Click on the door to the Audience Chamber at (H-5) for a cutscene.", ["|61"] = "Speak to Goggehn in the Bastokan Embassy to receive promotion to Rank 5.", ["|7"] = "Click the Audience Chamber in Ru'Lude Gardens (H-5) after obtaining all 3 Magicites for a cutscene and your reward (either an Airship Pass,", ["|8"] = "Return to Goggehn in the Bastokan Embassy to complete the mission, receive 10,000 Gil and Message to Jeuno (Bastok).", ["|9"] = "Gain access to the Tenshodo by completing the quest Tenshodo Membership if you have enough fame."}},
    [14] = {code = "Bastok 5-1", s = {["|1"] = "Players who are on the same Mission (5-1 or higher) with the New Fei'Yin seal, or have completed it for their current Nation, will be able", ["|2"] = "Speak to a Gate Guard.", ["|3"] = "Speak to Naji for a cutscene, and to receive the New Fei'Yin seal.", ["|4"] = "Go to Fei'Yin (located in the northeast corner of Beaucedine Glacier) for a cutscene with Zeid.", ["|5"] = "Head to Qu'Bia Arena at (K-8) map 1 and prepare for a BC, all buffs will wear upon entering.", ["|6"] = "Return to Naji to complete the Mission.", ["|7"] = "Zoning to Metalworks directly after finishing the last Mission, will cause the Metalworks music to be replaced with \"Despair (Memoro de la"}},
    [15] = {code = "Bastok 5-2", s = {["|1"] = "Malduc right beside Naji will give the mission.", ["|10"] = "Head up the stairs and you will be on the second \"level\".", ["|11"] = "Next, get to the top left part of the map and walk back down the set of stairs and you'll be back on the first \"level\".", ["|12"] = "Work your way into the center of the map from here and you will be in an outdoor courtyard.", ["|13"] = "Inside, walk out of the hallway and turn right.", ["|14"] = "Once on the second level, you will be overlooking a room below.", ["|15"] = "Follow the teleporters four times until you reach a new map.", ["|16"] = "The Shadow Lord has 2 forms.", ["|17"] = "While immune to magic, he will use Dark Nova (AOE Darkness damage) and can cast Black Magic.", ["|18"] = "During physical immunity, he can use a variety of TP attacks, including Giga Slash, Kick Back and Umbra Smash.", ["|19"] = "Defeating the first form will get you a cutscene.", ["|2"] = "Click on the Door: President's Office next to Iron Eater and enter to speak to President Karst for another cutscene.", ["|20"] = "The second form will only use AoE attacks, but has less HP (approximately 4,000 HP).", ["|3"] = "Castle Zvahl Keep Home Point #1 is fastest way.", ["|4"] = "After you clear the BCNM, you'll get another cutscene.", ["|5"] = "Return to the President for your reward: Rank 6 and 20,000 Gil.", ["|6"] = "Head for Xarcabard.", ["|7"] = "Enter Castle Zvahl Baileys, follow the one-way path until you come to the first intersection.", ["|8"] = "Turn left and follow the right wall until you reach the next map.", ["|9"] = "On the next map, turn right and head all the way to the top right corner of the map."}},
    [16] = {code = "Bastok 6-1", s = {["|1"] = "You'll be instructed to go see Medicine Eagle (G/H-6, all the way north) in Bastok Mines", ["|2"] = "You must then speak with Drake Fang in Zeruhn Mines (H-6), near the boat.", ["|3"] = "You will get a cutscene telling you to go to Western Altepa Desert.", ["|4"] = "In Western Altepa Desert, seek out a ??? on the west side of (G-8), in-between 3 glowing rocks.", ["|5"] = "Once defeated, check the ??? again to receive the Altepa moonpebble.", ["|6"] = "Return to Bastok Mines HP #3 and speak with Tall Mountain (J-7) on the bottom level near the restricted area.", ["|7"] = "After the cutscene, the Mission will be complete."}},
    [17] = {code = "Bastok 6-2", s = {["|1"] = "Speak to Naji for a cutscene.", ["|10"] = "Head back to Naji for a final cutscene and your reward.", ["|2"] = "Head to Norg and speak with Gilgamesh behind the Oaken Door at (K-8).", ["|3"] = "Obtain 1 Adaman Ore for every 6 players in your party/alliance.", ["|4"] = "Proceed to Yhoator Jungle (I-5) and enter Ifrit's Cauldron.", ["|5"] = "You will have to reach a ??? which isn't too far inside (Map 1, H-7).", ["|6"] = "Once inside, head left at the first intersection, and then on the next intersection go right.", ["|7"] = "Buff up and prepare to fight.", ["|8"] = "Upon defeating Magma, it will drop 6 Rare/Ex Frag Rocks.", ["|9"] = "When everyone has their Frag Rock, head back to Norg and trade it to Gilgamesh for a cutscene."}},
    [18] = {code = "Bastok 7-1", s = {["|1"] = "Speak to Cid in the Metalworks (H-8) for a cutscene.", ["|2"] = "You will be instructed to go to Ro'Maeve, which can be accessed from The Sanctuary of Zi'Tah at (F-5).", ["|3"] = "You are looking for a ???, which can spawn in the following locations, listed from west to east:", ["|4"] = "Check the ??? to spawn 2 Golem NMs named Mokkurkalfi.", ["|5"] = "Check the ??? again to receive the Reinforced cermet Key Item.", ["|6"] = "Return to Cid for another cutscene."}},
    [19] = {code = "Bastok 7-2", s = {["|1"] = "Speak with the President Karst in the Metalworks at the President's Office for details on the Mission.", ["|2"] = "Speak with Hilda at the Steaming Sheep at (E-6) in Port Bastok HP #3.", ["|3"] = "You will have to travel to the Waughroon Shrine, which can be reached through the Palborough Mines.", ["|4"] = "Interact with the Burning Circle to enter the BCNM Battle \"On My Way\".", ["|5"] = "Upon completion, you will receive a Letter from Werei.", ["|6"] = "Return to the Metalworks and speak to Karst.", ["|7"] = "Speak to Gumbah in Bastok Mines in the house next to home point #3 @ (J-7) (go up the stairs to second floor and cross the bridge) for a", ["|8"] = "Cornelia's door (behind President Karst) is no longer locked."}},
    [20] = {code = "Bastok 8-1", s = {["|1"] = "Visit Iron Eater at the President's Office in Metalworks.", ["|10"] = "The ??? you need is on the floor infront of the mural in the room at (H-8).", ["|11"] = "Return to Iron Eater for a final cutscene.", ["|2"] = "Head for the tunnel at (G-5) in Western Altepa Desert to enter Quicksand Caves Map 7.", ["|3"] = "Make your way to (H-8) where you'll have to open the weighted Ornate Door.", ["|4"] = "Open the next weighted Ornate Door at (I-10).", ["|5"] = "Clear out the room, and then check the ??? in front of the Galka Statue to spawn 3 level 70 Antica NMs.", ["|6"] = "Check the Galka Statue again once the bodies have disappeared for a cutscene with Zeid.", ["|7"] = "Leave and proceed to (D-12) of Western Altepa Desert and enter Quicksand Caves Map 5.", ["|8"] = "Inside, head through the eastern weighted Ornate Doors at (K-8) this will take you to Map 6.", ["|9"] = "Go east to another weight device at (G-8) and proceed east again."}},
    [21] = {code = "Bastok 8-2", s = {["|1"] = "Visit Drake Fang in Zeruhn Mines (H-6).", ["|2"] = "Head for Kuftal Tunnel Map 1.", ["|3"] = "Interact with the ???.", ["|4"] = "Sneak up and head down around to reach the second ??? down the cliff, directly under the first one.", ["|5"] = "Checking the ??? will spawn 3 level 68 NM Ghosts: Dervo's Ghost, Gizerl's Ghost, and Gordov's Ghost.", ["|6"] = "Check the ??? again for a cutscene and the Old piece of wood.", ["|7"] = "Return to Drake Fang for a final cutscene."}},
    [22] = {code = "Bastok 9-1", s = {["|1"] = "Visit Alois in the President's Office Conference Room in Metalworks (J-8).", ["|2"] = "Head to Rabao and speak to Dancing Wolf in (G-7) for a cutscene.", ["|3"] = "Proceed to Gustav Tunnel (G-6) on Map 2, and reach the ??? located in the pond.", ["|4"] = "Checking the ??? will spawn Gigaplasm, a slime NM.", ["|5"] = "Defeat all of them and Sneak everyone to the ???.", ["|6"] = "Return to Rabao and speak to Dancing Wolf for a cutscene.", ["|7"] = "Head back to Alois to finish the Mission."}},
    [23] = {code = "Bastok 9-2", s = {["|1"] = "Talk to Iron Eater in Metalworks (J-8) for a cutscene.", ["|2"] = "Make your way to the Throne Room in Castle Zvahl Keep HP #1.", ["|3"] = "Gather up, and enter the \"Where Two Paths Converge\" fight when ready.", ["|4"] = "You'll be facing a two-part fight against Zeid.", ["|5"] = "Win the fight for another cutscene.", ["|6"] = "Return to the President's Office and speak to Iron Eater for another cutscene.", ["|7"] = "You will be rewarded, and complete the Bastok story!"}},
